create extension if not exists "pgcrypto";

create type public.measurement_state as enum ('raw', 'cooked', 'as_served');
create type public.food_type as enum ('generic', 'branded', 'custom', 'recipe');
create type public.meal_type as enum ('breakfast', 'lunch', 'evening', 'dinner', 'snack');
create type public.goal_type as enum ('maintain', 'lose', 'gain');
create type public.invitation_status as enum ('pending', 'accepted', 'declined', 'cancelled');
create type public.group_role as enum ('owner', 'member');

create table public.profiles (
  id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade,
  name text not null default 'Member', email text not null, avatar_url text, age integer check (age is null or age between 13 and 130), height_cm numeric check (height_cm is null or height_cm > 0), current_weight_kg numeric check (current_weight_kg is null or current_weight_kg > 0),
  calorie_target numeric not null default 2200 check (calorie_target >= 0), protein_target numeric not null default 120 check (protein_target >= 0), carb_target numeric not null default 260 check (carb_target >= 0), fat_target numeric not null default 70 check (fat_target >= 0), goal public.goal_type not null default 'maintain',
  share_calories boolean not null default true, share_protein boolean not null default true, share_carbs boolean not null default false, share_fat boolean not null default false, share_weight boolean not null default false, share_meal_details boolean not null default false, share_workout_status boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table public.foods (
  id uuid primary key default gen_random_uuid(), name text not null, brand text, description text, food_type public.food_type not null default 'generic', measurement_state public.measurement_state not null default 'as_served',
  calories_per_100g numeric not null check (calories_per_100g >= 0), protein_per_100g numeric not null default 0 check (protein_per_100g >= 0), carbs_per_100g numeric not null default 0 check (carbs_per_100g >= 0), fat_per_100g numeric not null default 0 check (fat_per_100g >= 0), fiber_per_100g numeric not null default 0 check (fiber_per_100g >= 0),
  source text not null default 'Custom', source_id text, created_by uuid references auth.users(id) on delete cascade, is_global boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table public.recipes (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, description text, total_cooked_weight numeric not null check (total_cooked_weight > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.recipe_ingredients (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.recipes(id) on delete cascade, food_id uuid not null references public.foods(id) on delete restrict, quantity_grams numeric not null check (quantity_grams > 0));
create table public.food_logs (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, food_id uuid references public.foods(id) on delete set null, recipe_id uuid references public.recipes(id) on delete set null, meal public.meal_type not null, quantity_grams numeric not null check (quantity_grams > 0), measurement_state public.measurement_state not null,
  calories numeric not null check (calories >= 0), protein numeric not null check (protein >= 0), carbs numeric not null check (carbs >= 0), fat numeric not null check (fat >= 0), fiber numeric not null default 0 check (fiber >= 0), logged_at timestamptz not null default now(), created_at timestamptz not null default now(), check (food_id is not null or recipe_id is not null)
);
create table public.weight_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, weight_kg numeric not null check (weight_kg > 0), logged_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.meal_templates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.meal_template_items (id uuid primary key default gen_random_uuid(), meal_template_id uuid not null references public.meal_templates(id) on delete cascade, food_id uuid references public.foods(id) on delete restrict, recipe_id uuid references public.recipes(id) on delete restrict, quantity_grams numeric not null check (quantity_grams > 0), measurement_state public.measurement_state not null, check (food_id is not null or recipe_id is not null));
create table public.groups (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 80), created_by uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.group_members (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.group_role not null default 'member', joined_at timestamptz not null default now(), unique(group_id, user_id));
create table public.group_invitations (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, invited_by uuid not null references auth.users(id) on delete cascade, invited_user_id uuid not null references auth.users(id) on delete cascade, status public.invitation_status not null default 'pending', created_at timestamptz not null default now(), responded_at timestamptz, check (invited_by <> invited_user_id), unique(group_id, invited_user_id));
create table public.group_activity (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, activity_type text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

create index food_logs_user_logged_at_idx on public.food_logs(user_id, logged_at desc); create index weight_logs_user_logged_at_idx on public.weight_logs(user_id, logged_at desc); create index foods_name_idx on public.foods using gin (to_tsvector('simple', name)); create index groups_created_by_idx on public.groups(created_by); create index group_members_group_idx on public.group_members(group_id); create index group_members_user_idx on public.group_members(user_id); create index invitations_recipient_status_idx on public.group_invitations(invited_user_id, status);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger foods_updated before update on public.foods for each row execute function public.set_updated_at(); create trigger recipes_updated before update on public.recipes for each row execute function public.set_updated_at(); create trigger templates_updated before update on public.meal_templates for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (user_id, name, email) values (new.id, coalesce(new.raw_user_meta_data->>'name', 'Member'), coalesce(new.email, '')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.create_group_owner() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.group_members(group_id, user_id, role) values (new.id, new.created_by, 'owner'); return new; end; $$;
create trigger on_group_created after insert on public.groups for each row execute function public.create_group_owner();
create or replace function public.is_group_member(target_group uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.group_members where group_id = target_group and user_id = auth.uid()); $$;
create or replace function public.is_group_owner(target_group uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.group_members where group_id = target_group and user_id = auth.uid() and role = 'owner'); $$;
create or replace function public.accept_group_invitation(invitation_id uuid) returns void language plpgsql security definer set search_path = public as $$ declare invite public.group_invitations; begin select * into invite from public.group_invitations where id = invitation_id and invited_user_id = auth.uid() and status = 'pending' for update; if not found then raise exception 'Invitation not found or unavailable'; end if; update public.group_invitations set status = 'accepted', responded_at = now() where id = invitation_id; insert into public.group_members(group_id, user_id, role) values (invite.group_id, auth.uid(), 'member') on conflict do nothing; end; $$;
create or replace function public.decline_group_invitation(invitation_id uuid) returns void language plpgsql security definer set search_path = public as $$ begin update public.group_invitations set status = 'declined', responded_at = now() where id = invitation_id and invited_user_id = auth.uid() and status = 'pending'; if not found then raise exception 'Invitation not found or unavailable'; end if; end; $$;
create or replace function public.group_progress(target_group uuid, selected_day date) returns table(user_id uuid, name text, calorie_target numeric, protein_target numeric, calories numeric, protein numeric, weight_kg numeric) language sql stable security definer set search_path = public as $$ select p.user_id, p.name, case when p.share_calories then p.calorie_target end, case when p.share_protein then p.protein_target end, case when p.share_calories then coalesce(sum(fl.calories), 0) end, case when p.share_protein then coalesce(sum(fl.protein), 0) end, case when p.share_weight then (select wl.weight_kg from public.weight_logs wl where wl.user_id = p.user_id order by wl.logged_at desc limit 1) end from public.group_members gm join public.profiles p on p.user_id = gm.user_id left join public.food_logs fl on fl.user_id = p.user_id and fl.logged_at::date = selected_day where gm.group_id = target_group and public.is_group_member(target_group) group by p.user_id, p.name, p.share_calories, p.share_protein, p.share_weight, p.calorie_target, p.protein_target; $$;

alter table public.profiles enable row level security; alter table public.foods enable row level security; alter table public.recipes enable row level security; alter table public.recipe_ingredients enable row level security; alter table public.food_logs enable row level security; alter table public.weight_logs enable row level security; alter table public.meal_templates enable row level security; alter table public.meal_template_items enable row level security; alter table public.groups enable row level security; alter table public.group_members enable row level security; alter table public.group_invitations enable row level security; alter table public.group_activity enable row level security;
create policy "own profile" on public.profiles for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "read permitted foods" on public.foods for select using (is_global or created_by = auth.uid()); create policy "create private foods" on public.foods for insert with check (created_by = auth.uid() and not is_global); create policy "edit private foods" on public.foods for update using (created_by = auth.uid() and not is_global) with check (created_by = auth.uid() and not is_global); create policy "remove private foods" on public.foods for delete using (created_by = auth.uid() and not is_global);
create policy "own recipes" on public.recipes for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "own recipe ingredients" on public.recipe_ingredients for all using (exists (select 1 from public.recipes r where r.id = recipe_id and r.user_id = auth.uid())) with check (exists (select 1 from public.recipes r where r.id = recipe_id and r.user_id = auth.uid()));
create policy "own logs" on public.food_logs for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "own weights" on public.weight_logs for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "own templates" on public.meal_templates for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "own template items" on public.meal_template_items for all using (exists (select 1 from public.meal_templates t where t.id = meal_template_id and t.user_id = auth.uid())) with check (exists (select 1 from public.meal_templates t where t.id = meal_template_id and t.user_id = auth.uid()));
create policy "read member groups" on public.groups for select using (public.is_group_member(id)); create policy "create groups" on public.groups for insert with check (created_by = auth.uid()); create policy "owners update groups" on public.groups for update using (public.is_group_owner(id)); create policy "owners delete groups" on public.groups for delete using (public.is_group_owner(id));
create policy "read fellow members" on public.group_members for select using (public.is_group_member(group_id)); create policy "owners remove members" on public.group_members for delete using (public.is_group_owner(group_id) and user_id <> auth.uid());
create policy "read own or owner invitations" on public.group_invitations for select using (invited_user_id = auth.uid() or public.is_group_owner(group_id)); create policy "owners invite" on public.group_invitations for insert with check (public.is_group_owner(group_id) and invited_by = auth.uid() and status = 'pending'); create policy "owners cancel invites" on public.group_invitations for update using (public.is_group_owner(group_id)) with check (status = 'cancelled');
create policy "member activity" on public.group_activity for select using (public.is_group_member(group_id)); create policy "member own activity" on public.group_activity for insert with check (public.is_group_member(group_id) and user_id = auth.uid());
grant execute on function public.accept_group_invitation(uuid), public.decline_group_invitation(uuid), public.group_progress(uuid, date) to authenticated;

-- Group management helpers: owners can invite an existing account by email without exposing profiles globally.
create or replace function public.invite_group_member(target_group uuid, invited_email text)
returns uuid language plpgsql security definer set search_path = public as $$
declare target_user uuid; invitation_id uuid;
begin
  if not public.is_group_owner(target_group) then raise exception 'Only the group owner can invite members'; end if;
  select user_id into target_user from public.profiles where lower(email) = lower(trim(invited_email)) limit 1;
  if target_user is null then raise exception 'No MacroTrack account was found for that email'; end if;
  if target_user = auth.uid() then raise exception 'You cannot invite yourself'; end if;
  if exists (select 1 from public.group_members where group_id = target_group and user_id = target_user) then raise exception 'That person is already a member'; end if;
  insert into public.group_invitations(group_id, invited_by, invited_user_id, status)
  values (target_group, auth.uid(), target_user, 'pending')
  on conflict (group_id, invited_user_id) do update set status = 'pending', invited_by = auth.uid(), created_at = now(), responded_at = null
  returning id into invitation_id;
  return invitation_id;
end; $$;

grant execute on function public.invite_group_member(uuid, text) to authenticated;
